export default class Action {
    icon;
    name;
    label;
    description;
    action;
    constructor(options) {
        this.icon = options.icon || "lightning";
        this.name = options.name;
        this.label = options.label || options.name;
        this.description = options.description;
        this.action = options.action;
    }
    run() {
        return this.action();
    }
}
